INSERT INTO tool_guides (slug, title, eyebrow, grades, duration, summary, what_it_is, example_title, example, app_url, steps, tips) VALUES (N'qr-code-generator', N'Classroom QR Code Generator', N'Digital classroom tool', N'K–12 · teacher directed', N'2–5 minutes', N'Turn links, short text, or task directions into printable QR codes for stations, choice boards, research, review, and family communication.', N'This tool creates several QR codes at once. It works in any subject because the code can point to a video, article, audio clip, simulation, form, or teacher-created direction. The QR code is only the doorway; the learning value comes from the task you place beside it.', N'Classroom example: ecosystem stations', N'Create four QR codes that open a short video, a diagram, a vocabulary page, and a data table about one ecosystem. Student teams rotate, record one piece of evidence at each station, and finish by explaining how two organisms depend on each other.', NULL, N'["Decide what students should do after scanning, such as collect evidence, compare two sources, listen for a detail, or submit an explanation.","Enter the link or text, generate the code, and test every code on a second device before printing.","Print a clear task, expected time, and success criteria beside each code so the activity does not stop at scanning."]', N'["Print codes at least one inch square and leave white space around them.","Prepare a short URL or paper alternative in case a device or network is unavailable.","Do not place student names, grades, or other personal information directly inside a QR code."]');
INSERT INTO tool_guides (slug, title, eyebrow, grades, duration, summary, what_it_is, example_title, example, app_url, steps, tips) VALUES (N'random-group-generator', N'Random Group Generator', N'Classroom management tool', N'Grades 1–12', N'1–3 minutes', N'Create partners or groups quickly for discussion, problem solving, labs, reading, review, and learning stations.', N'Random grouping reduces the time spent assigning teams and gives students opportunities to work with different classmates. It is not a replacement for teacher judgment. You can still adjust a result when students need language support, accessibility accommodations, or a safer working relationship.', N'Classroom example: three-round evidence exchange', N'In round one, pairs compare their answers to one problem. Regroup students for round two so each person explains a previous partner’s strategy. In round three, groups of four decide which strategy is clearest and prepare one shared explanation.', NULL, N'["Paste student names and choose group size or number of groups.","Review the result for support needs, group balance, and classroom dynamics before displaying it.","Assign useful roles such as facilitator, recorder, materials manager, checker, and reporter."]', N'["Begin with pairs when a routine is new, then increase group size for a more complex task.","Pre-assign a reliable partner when a student needs extra communication or emotional support.","Avoid saving or projecting full student names when initials, first names, or seat numbers are enough."]');
INSERT INTO tool_guides (slug, title, eyebrow, grades, duration, summary, what_it_is, example_title, example, app_url, steps, tips) VALUES (N'sunflower-spinner', N'Sunflower Classroom Spinner', N'Random selection and practice', N'K–12', N'3–5 minutes', N'Add terms, questions, student numbers, topics, or challenge levels to a sunflower wheel and use the result to begin a classroom task.', N'This is a customizable random spinner for any subject. A spin should lead to a clear action: define, solve, compare, sketch, justify, demonstrate, or ask a follow-up question.', N'Classroom example: math representation review', N'Add “number line,” “equation,” “table,” “diagram,” and “words” to the wheel. After a spin, students represent the same problem in the selected form and explain what the representation makes easier to see.', N'/teaching-tools/sunflower-spinner/sunflower-spinner.html', N'["Add 8–16 items from one lesson or review goal so the labels stay readable.","Model exactly what students do after the wheel stops.","Give quiet thinking time before asking for an answer, then invite a second student to add evidence or another method."]', N'["Use student numbers instead of full names when the wheel is projected.","Mark easier and stretch items so students can enter the task at different levels.","Allow students to request a hint or a partner after a random selection so participation stays safe."]');
INSERT INTO tool_guides (slug, title, eyebrow, grades, duration, summary, what_it_is, example_title, example, app_url, steps, tips) VALUES (N'word-list-library', N'Multilingual Vocabulary Library', N'Reusable planning library', N'Teacher tool · K–12', N'5–10 minutes per list', N'Save focused vocabulary lists for later use in games, cards, booklets, and printable activities. Chinese, pinyin, and English fields are supported.', N'The library turns repeated typing into a reusable collection. It is especially useful for language teaching, but any teacher can store terms, optional pronunciation notes, and short definitions. Lists are saved in the current browser.', N'Classroom example: one list, three uses', N'On Monday, build a twelve-term unit list and run a quick recognition check. On Wednesday, use the same terms in a spinner or review game. On Friday, turn them into a mini booklet for retrieval practice.', N'/teaching-tools/word-list-library/word-list-library.html', N'["Keep each list connected to one clear goal, such as “Cell Structure: 12 Core Terms.”","Check spelling, pronunciation, and definitions before saving.","Use a name that includes the course, unit, and level so the list is easy to find later."]', N'["Keep a core list to 8–16 terms when students are new to the topic.","Separate words students should recognize from terms they must spell or define precisely.","Browser data can be cleared, so export or back up important lists."]');
INSERT INTO tool_guides (slug, title, eyebrow, grades, duration, summary, what_it_is, example_title, example, app_url, steps, tips) VALUES (N'question-bank-library', N'Question Bank Library', N'Reusable classroom questions', N'Grades 2–12', N'10–15 minutes per set', N'Save reviewed questions, answers, choices, and tags for discussions, quizzes, review games, and formative checks.', N'A question bank is a home for teacher-reviewed prompts, not a pile of unexamined questions. A strong bank is tied to one learning goal and mixes recall, application, explanation, and open response.', N'Classroom example: layered science review', N'Level one asks students to identify a cell structure. Level two asks for its function. Level three asks students to predict what would happen if it stopped working. One game board can then serve several readiness levels.', N'/teaching-tools/question-bank-library/question-bank-library.html', N'["Write the learning goal first, then create 8–15 questions that genuinely check it.","Add hints, sentence starters, diagrams, or challenge prompts for different learners.","Check answers, difficulty, wording, and cultural context before use; revise after seeing student responses."]', N'["Let one question measure one main target.","Mix retrieval with sorting, explaining, comparing, and applying.","Never add student names, grades, or other personal information to a shared question bank."]');
INSERT INTO tool_guides (slug, title, eyebrow, grades, duration, summary, what_it_is, example_title, example, app_url, steps, tips) VALUES (N'vocabulary-booklet', N'Vocabulary Mini Booklet', N'Printable independent practice', N'Grades 1–8', N'5–10 minutes', N'Turn a short term list into a foldable booklet for reading, sketching, defining, matching, or home review.', N'The booklet turns loose terms into a personal material students can mark, revisit, and carry. It works best with a small number of high-value words instead of every term in a unit.', N'Classroom example: landform field guide', N'Each page includes one landform term. Beginning students match a picture and definition; more independent students add a real location and one comparison sentence. Partners trade booklets and quiz each other at the end.', N'/teaching-tools/vocabulary-booklet/vocabulary-booklet.html', N'["Choose 6–12 terms students truly need this week.","Assign a useful action for each term: read, trace, sketch, match, define, or use in a sentence.","Print and fold one sample before making a class set so you can check page direction and type size."]', N'["Use large type and limited text for younger students.","Bring the booklet back several days later for spaced review.","Check that every definition matches the exact meaning used in the current unit."]');
INSERT INTO tool_guides (slug, title, eyebrow, grades, duration, summary, what_it_is, example_title, example, app_url, steps, tips) VALUES (N'word-sudoku', N'Vocabulary Sudoku', N'Recognition and logic practice', N'Grades 3–9', N'8–12 minutes', N'Turn nine words or concepts into a printable 9×9 Sudoku for repeated recognition during logical problem solving.', N'Vocabulary Sudoku keeps the familiar rule that each item appears once in every row, column, and box, but replaces numbers with words or icons. It is best for reviewing terms students have already met.', N'Classroom example: geometry review station', N'Use nine shape names with simple icons. After solving, students circle three terms and write one accurate property for each. The logic puzzle ends with evidence of subject understanding.', N'/low-prep/word-sudoku/word-sudoku-widget.html', N'["Choose nine visually distinct terms students already recognize.","Use icons or short definitions for support, then remove those supports as students become fluent.","Model one smaller section before students work independently or with a partner."]', N'["Do not introduce nine unfamiliar terms through the puzzle.","Offer a partially completed version to students new to Sudoku.","Provide an answer key for self-checking so teacher time goes to students who are genuinely stuck."]');
INSERT INTO tool_guides (slug, title, eyebrow, grades, duration, summary, what_it_is, example_title, example, app_url, steps, tips) VALUES (N'word-cloud', N'Classroom Word Cloud', N'Quick recognition and sorting', N'Grades 1–9', N'5 minutes', N'Generate a printable word cloud for term hunts, sorting, listening checks, unit previews, and retrieval practice.', N'A word cloud places vocabulary in a non-linear visual space, which asks students to scan and recognize actively. It becomes an instructional activity when you add a clear task such as find, classify, connect, or explain.', N'Classroom example: one-minute concept sort', N'Mix vocabulary from solids, liquids, gases, and changes of state. Students mark each category with a different symbol, compare with a partner, and explain one term they found difficult to place.', N'/low-prep/word-cloud/word-cloud-widget.html', N'["Enter 10–25 terms from one unit.","Give students a rule, such as “circle causes, underline effects, and box evidence.”","Finish by asking students to speak or write with selected terms."]', N'["Avoid too many labels or translations on one page.","For black-and-white printing, use circles, boxes, and underlines instead of color alone.","Ask students to explain a category decision so the task is more than a speed search."]');
INSERT INTO tool_guides (slug, title, eyebrow, grades, duration, summary, what_it_is, example_title, example, app_url, steps, tips) VALUES (N'independent-reading', N'Independent Reading Packet Builder', N'Reading and substitute-ready resource', N'Grades 3–12', N'10–20 minutes', N'Turn a teacher-selected text and questions into a printable packet with comprehension, rewriting, and storyboard tasks.', N'The tool formats the packet, while the teacher remains responsible for text difficulty, copyright, background knowledge, and question quality. Choose a text students can understand mostly on their own with a manageable stretch.', N'Classroom example: three-pass reading', N'On the first pass, students mark people, places, or key terms. On the second, they sequence three events or ideas. On the third, they redraw one section and add a two-sentence caption. A substitute can follow the same page sequence without inventing new directions.', NULL, N'["Paste a teacher-reviewed text that you have permission to use.","Order questions from finding information to inference and personal response.","Read the downloaded packet from beginning to end and check page breaks, answer space, and type size."]', N'["Do not paste a copyrighted full book or an unauthorized long text.","Provide vocabulary or sentence support only where it helps students work independently.","Give open questions enough writing space and a clear success criterion."]');
INSERT INTO tool_guides (slug, title, eyebrow, grades, duration, summary, what_it_is, example_title, example, app_url, steps, tips) VALUES (N'tear-paper-bingo', N'Tear-Paper Bingo', N'Listening and recognition game', N'Grades 1–8', N'8–12 minutes', N'Students tear a term only when it appears at one end of their paper strip, combining listening, recognition, and simple strategy.', N'Unlike regular Bingo, the order of the terms and the “tear from an end” rule create a small strategy problem. Read a term, give a definition, show an example, or place the answer inside a question so one strip supports several levels.', N'Classroom example: from answer to clue', N'In round one, call “evaporation.” In round two, say “liquid water changes into a gas.” In round three, describe a wet sidewalk drying after the sun appears. The same terms now require deeper recognition.', NULL, N'["Have each student write eight familiar terms in a different order on a paper strip.","Model two calls and confirm that students may tear only from either end.","In a later round, replace direct terms with definitions, examples, equations, or clues."]', N'["Use content students have already learned so the challenge comes from retrieval.","Collect torn paper in one place and reserve one minute for cleanup.","After a student wins, let that student read or create the next clue so the game continues to serve learning."]');
INSERT INTO tool_guides (slug, title, eyebrow, grades, duration, summary, what_it_is, example_title, example, app_url, steps, tips) VALUES (N'would-you-rather', N'Would You Rather Prompt Builder', N'Low-pressure discussion activity', N'Grades 2–12', N'5–15 minutes', N'Create either-or prompts that help students choose, justify, compare, predict, and ask follow-up questions.', N'An either-or question gives every student an immediate entry point: choose first, then build a reason. It works across subjects when both options are plausible and the reasoning matters more than the vote.', N'Classroom example: choose the better strategy', N'Display “Would you rather solve this problem with a table or a diagram?” Students choose a side, explain what their representation reveals, then pair with someone who chose differently and summarize the other method.', NULL, N'["Enter pairs connected to familiar content and avoid sensitive personal topics.","Display one prompt and give the class ten seconds of quiet thinking time.","Students choose, explain with evidence, and ask a partner one follow-up question."]', N'["Make “Why?” or “What is your evidence?” the required second step.","Allow a third option when students can explain it well.","Use imagined scenarios instead of personal surveys when a topic touches family, health, food, or money."]');
INSERT INTO tool_guides (slug, title, eyebrow, grades, duration, summary, what_it_is, example_title, example, app_url, steps, tips) VALUES (N'jeopardy', N'Jeopardy Review Game', N'Whole-class review', N'Grades 3–12', N'15–30 minutes', N'Arrange questions by category and difficulty for team discussion, timed responses, scoring, and review across any subject.', N'The value of Jeopardy is not only speed or points. A well-designed board gives teams time to discuss, requires explainable answers, and includes a role for every student.', N'Classroom example: four kinds of evidence', N'Use columns for identify, calculate, compare, and explain. Teams rotate the recorder and spokesperson. At the end, each student chooses one missed question and writes why the corrected answer makes sense.', NULL, N'["Make each column a clear category and let each question check one main target.","Give teams 15–30 seconds to discuss before randomly selecting a spokesperson.","End by revisiting the two most-missed questions and asking every student to record a correct response."]', N'["Mix quick retrieval with questions that reward careful thinking.","Write acceptable-answer criteria in advance when more than one response could work.","Control sound and competition so the game supports review instead of overwhelming it."]');
INSERT INTO tool_guides (slug, title, eyebrow, grades, duration, summary, what_it_is, example_title, example, app_url, steps, tips) VALUES (N'character-race', N'Term Race Vocabulary Finder', N'Recognition and partner activity', N'Grades 1–8', N'5–12 minutes', N'Arrange words or short terms in a wheel and grid, then have partners give clues, find the target, and switch roles.', N'The activity combines visual scanning with spoken clues. Begin by reading a term directly, then increase the challenge with a definition, example, property, translation, or sentence clue.', N'Classroom example: concept detective', N'Add terms from a current unit. In round one, partners read the term. In round two, they give a definition without saying it. In round three, they explain how two terms connect, shifting the activity from speed to subject reasoning.', NULL, N'["Choose 12–20 familiar terms and generate a large, readable version.","Partner A gives a clue; Partner B finds and marks the term.","Switch roles every five clues, then use three selected terms in an explanation."]', N'["Use a single ring and larger type for younger students.","Prioritize accuracy before adding a timer.","Keep one round under twenty items; split a larger unit into two focused sets."]');
INSERT INTO tool_guides (slug, title, eyebrow, grades, duration, summary, what_it_is, example_title, example, app_url, steps, tips) VALUES (N'maze-generator', N'Question-and-Answer Maze Generator', N'Printable review task', N'Grades 3–12', N'10–15 minutes', N'Turn eight questions and answers into an editable maze so students follow correct responses and leave a visible reasoning path.', N'The maze converts a sequence of short checks into a visual path. It works well for formative review because the first wrong turn often reveals the exact idea that needs reteaching.', N'Classroom example: fraction equivalence maze', N'Each question shows one fraction and students choose an equivalent form. After reaching the end, they select four correct pairs and explain the strategy they used. Review the first wrong turn rather than checking only the final destination.', NULL, N'["Choose eight focused questions with clear answers.","Download the PowerPoint and check every branch, label, and font size.","After students solve independently, have partners compare paths and explain the first disagreement."]', N'["Use distractors based on common misconceptions instead of random wrong answers.","Give beginners one worked example or visual cue.","Walk the correct path yourself before printing to make sure every branch connects."]');
INSERT INTO tool_guides (slug, title, eyebrow, grades, duration, summary, what_it_is, example_title, example, app_url, steps, tips) VALUES (N'tarsia-puzzle', N'Tarsia Matching Puzzle Generator', N'Cut-and-rebuild review task', N'Grades 2–12', N'10–20 minutes', N'Turn 9 or 18 matching pairs into triangular pieces that students rebuild by matching every interior edge.', N'A Tarsia puzzle breaks a completed large triangle into smaller triangular pieces. Students retrieve vocabulary, meanings, pronunciations, representations, or answers while testing how each piece fits with its neighbors.', N'Classroom example: Chinese vocabulary in three passes', N'First match Chinese words to Twemoji pictures. Reuse the same word set on another day with pinyin, then with English meanings. Students explain two matches aloud before checking the completed triangle.', NULL, N'["Choose a quick 9-pair puzzle or a standard 18-pair puzzle.","Review every automatically filled English, pinyin, or picture match before downloading.","Print the cut sheet and answer key, then mix each student or group set in a labeled envelope."]', N'["Use short, unambiguous labels so they remain readable along triangle edges.","Avoid repeating the same answer on multiple edges unless you want more than one possible placement.","Print one test copy and solve it yourself before preparing a class set."]');
INSERT INTO articles (slug, category, title, description, read_time, intro, sections, related_tool_label, related_tool_href) VALUES (N'chinese-classroom-bingo-five-ways', N'Chinese Language Teaching', N'Five Ways to Use Bingo in Chinese Class: From Recognition to Real Language', N'Use one Bingo board to practice character recognition, listening, description, collaboration, and an observable exit task.', N'8 min read', N'["Bingo is easy to prepare, but it can quickly become a one-way routine in which the teacher reads and students circle. A stronger design adds one language action in each round. Students first recognize, then describe, question, or create.","The five versions below can share the same set of 9–16 terms. Before class, decide what you are actually checking: sound recognition, character recognition, meaning, or sentence production. Do not assess all four at once."]', N'[{"heading":"1. Hear the word and find the character","paragraphs":["Read the target word twice without displaying it. Students point first and mark second. Slow the first round, then return to natural speech."],"list":["Best for: grades one and up after a new set of terms.","Notice whether students rely on pinyin, character shape, or a neighbor.","Extend it by asking the class to place the word in a short sentence."]},{"heading":"2. Listen to a clue","paragraphs":["Instead of reading the word, give one understandable Chinese clue. For 雨伞, say: “下雨的时候，我带什么？” Students must understand the sentence before matching the word."],"callout":"Write clues with one most reasonable answer. If more than one answer could work, add “Explain why you chose it” to the rule."},{"heading":"3. Let students become the caller","paragraphs":["In pairs, Student A chooses and reads or describes a term. Student B finds it and repeats it before roles switch. While circulating, record patterns in pronunciation, recognition, and sentence use. Address one common pattern after the round instead of interrupting every exchange."]},{"heading":"4. Turn the board into Find Someone Who","paragraphs":["Replace single words with answerable prompts such as “likes dumplings,” “speaks another language,” or “enjoys sports on weekends.” Students ask complete questions and record a classmate’s name."],"list":["Model a respectful question and answer.","Let students skip a personal question they do not want to answer.","Limit how often one name can appear so students speak with more classmates."]},{"heading":"5. Add output after Bingo","paragraphs":["Do not end as soon as someone completes a line. Ask the winner to use three connected terms in a short story, or ask every student to choose one square for an exit sentence."],"callout":"Example sequence: 8 minutes of recognition Bingo, 4 minutes of partner description, and 3 minutes writing a sentence with three selected terms."},{"heading":"Teacher planning notes","paragraphs":["Use a 3×3 board, large images, and limited text for younger learners. Beginners may keep pinyin in the first round and cover it in the second. State the winning rule before play, and always end with visible evidence of learning: a sentence, an exit card, or a partner retell."]}]', N'Open the Tear-Paper Bingo activity', N'/teaching-tools/tear-paper-bingo');
INSERT INTO articles (slug, category, title, description, read_time, intro, sections, related_tool_label, related_tool_href) VALUES (N'teaching-mid-autumn-festival-grade-one', N'Culture & Celebrations', N'Teaching the Mid-Autumn Festival in Grade One: A 35-Minute Chinese Lesson', N'A low-elementary lesson using images, four core words, movement, moon sequencing, and culturally respectful language.', N'7 min read', N'["A first-grade celebration lesson does not need a complete historical account. Children benefit more from a few visible, physical, and memorable connections. A focused goal is enough: understand and say 月亮, 月饼, 家人, and 中秋节, and recognize that many people connect the celebration with family and the full moon.","The sequence below is designed for beginning Chinese learners. Use phrases such as “many families…” instead of “all Chinese people…” so different regions and family experiences have room."]', N'[{"heading":"0–5 minutes: begin with the moon","paragraphs":["Show a large full-moon image without naming the celebration. Ask what students notice and what shape they see. Students form a circle with their arms and repeat 月亮, 圆圆的月亮."]},{"heading":"5–12 minutes: teach four core words","paragraphs":["Teach 月亮, 月饼, 家人, and 中秋节 with one movement each: point upward, hold a pretend round cake, hug your shoulders, and draw a large circle. Use quick listening checks instead of requiring every character in writing."],"list":["Point upward when you hear 月亮.","Say the word when the image appears.","Correct the teacher when the teacher performs the wrong movement."]},{"heading":"12–20 minutes: tell a three-picture story","paragraphs":["Use three images: evening arrives; a family looks at the moon; people share mooncakes. Give each image only one or two short sentences and repeat 月亮 and 家人. Students retell with movement instead of memorizing a long legend."],"callout":"The Chang’e legend can be a separate lesson. The first meeting should establish a clear connection among the celebration, family, nighttime, and the full moon."},{"heading":"20–28 minutes: sequence the moon","paragraphs":["Give groups four moon-phase pictures. Students order them from curved to round while responding to 大一点, 小一点, and 圆圆的. Place the full moon beside the 中秋节 card at the end."]},{"heading":"28–35 minutes: make a small reflection card","paragraphs":["Students draw the moon and one food they would like to share with someone. Complete the frame “中秋节，我和家人一起____。” Students who are not ready to write can dictate or choose a picture card."],"list":["Exit check: identify three of the four core words.","Home connection: invite families to share whether and how they observe the festival; having no fixed tradition is also valid.","Teacher note: record whether the next lesson should focus on sound, meaning, or character recognition."]},{"heading":"A note about cultural language","paragraphs":["Avoid reducing the Mid-Autumn Festival to “a day for eating mooncakes,” and do not ask Chinese heritage students to represent one culture. Explain that the celebration looks different across places and families, then invite—but never require—students to share their own experiences."]}]', N'Browse theme-based teaching resources', N'/theme-activities');
INSERT INTO articles (slug, category, title, description, read_time, intro, sections, related_tool_label, related_tool_href) VALUES (N'ten-games-for-chinese-beginners', N'Chinese Language Teaching', N'Ten Quick Games for Beginning Chinese—Each With a Language Goal', N'Ten activities that take 3–12 minutes, with a purpose, simple rules, and teacher notes that keep the game focused on learning.', N'10 min read', N'["Beginners need frequent repetition, but “read it five more times” quickly loses attention. A useful game lets the same language appear in several different tasks. Begin by writing one goal, such as “Students can hear and point to eight color words,” and then choose the rule.","Each activity below takes 3–12 minutes. One or two games in a lesson is enough. The simpler the rule, the more time remains for Chinese."]', N'[{"heading":"1–2. Missing card / Listen and tap","paragraphs":["Display six cards, have students close their eyes, remove one, and ask 少了什么？ For Listen and Tap, two students share cards while the teacher reads a word or clue; students point before tapping."],"callout":"To reduce pure speed, require the winner to read the term or use it in a sentence before earning the point."},{"heading":"3–4. Classroom spinner / Mystery bag","paragraphs":["A spinner selects a term and a required language action. A mystery bag holds an object or image; students describe color, size, or category before guessing."]},{"heading":"5–6. Four corners / Either-or line","paragraphs":["Post four terms in classroom corners. Read a sentence, then have students move to a matching corner and explain to a partner. An either-or line uses 你喜欢 A 还是 B？ for a low-pressure opinion task."],"list":["Give five seconds of quiet thinking first.","Require one sentence after movement.","Rotate partners so students do not always talk with the same friend."]},{"heading":"7–8. Catch the teacher / Draw the message","paragraphs":["In Catch the Teacher, deliberately label an image incorrectly and let students correct with 不是……，是……. In Draw the Message, one student hears a location description, passes it along, and the final student draws the result before comparing it with the original."]},{"heading":"9–10. Character detective / Three-word story","paragraphs":["Character Detective asks students to find a known radical or character in classroom print, a word cloud, or a short text. Three-Word Story gives a group three familiar terms and a sentence frame for a two- to four-sentence story."],"callout":"A beginner story does not need to be complex. “小猫喜欢苹果。它去学校吃苹果。” already shows students transferring familiar language."},{"heading":"Plan the week, not ten separate games","paragraphs":["Use Missing Card on Monday for recognition, Four Corners on Wednesday for listening, and Three-Word Story on Friday for output. The vocabulary stays familiar while the task changes, letting the teacher observe a move from recognition to expression."]},{"heading":"Three common mistakes","list":["The explanation takes longer than the game: demonstrate one round, then add details.","The same students answer every time: use partner rehearsal, rotating roles, or random selection.","The game ends with a winner only: close with a retell, sentence, or exit card."]}]', N'Browse low-prep activities in Teaching Tools', N'/teaching-tools#low-prep-activities');
INSERT INTO articles (slug, category, title, description, read_time, intro, sections, related_tool_label, related_tool_href) VALUES (N'using-word-walls-for-chinese-vocabulary', N'Vocabulary Instruction', N'How to Use a Word Wall for Chinese Vocabulary—Not Just Decoration', N'Organize a Chinese word wall, make thoughtful pinyin decisions, and use five-minute routines that bring the words into speaking and writing.', N'8 min read', N'["A useful Chinese word wall is something students actively consult, not background decoration. Every item should serve a purpose: support character recognition, organize a sentence, compare meaning, or remind students to use unit language.","A smaller wall that students use is better than a crowded one. Add only 6–10 core terms each week, then move, combine, cover, or remove older terms as students become independent."]', N'[{"heading":"Choose a useful organization","paragraphs":["Topic groups—weather, food, family—are immediately understandable. Function groups—people, actions, places, connectors—often support expression more directly. Younger students benefit from color and small icons; older students can organize by radical, word class, or sentence function."]},{"heading":"Should pinyin stay forever?","paragraphs":["Pinyin is a scaffold, not a permanent label. Show it when a word is new, cover it with a foldable strip during recognition practice, and keep it later only for terms students still confuse. This supports pronunciation without training students to skip the characters."]},{"heading":"Five weekly five-minute routines","list":["Find a match: pair a word or image card with the wall entry.","One-minute sort: move five terms into categories and explain one choice.","Missing word: pause in a sentence and let students point to the word that completes it.","Build a sentence: choose one person, action, and place from the wall.","Exit word: each student uses one term; cover terms after use to increase variety."]},{"heading":"One week with a weather wall","paragraphs":["On Monday, post 晴天, 阴天, 下雨, 下雪, 刮风, 冷, and 热. On Tuesday, students point while listening. On Wednesday, they match weather with clothing. On Thursday, they connect ideas with 因为……所以……. On Friday, they write weather reports for two cities. The seven terms stay the same while the language task expands."]},{"heading":"Let students help maintain it","paragraphs":["Assign two weekly word-wall managers to check cards, add classroom discoveries to a candidate area, and notice the most-used terms. Students may submit example sentences, but the teacher reviews characters, pinyin, and context before posting."]},{"heading":"Teacher checklist","list":["Can a student in the back read it?","Has every term been used in an activity this week?","Does each image clarify rather than confuse?","Are there verbs and connectors, not only nouns?","Which terms are now independent and can come down?"]}]', N'Build a reusable vocabulary list', N'/teaching-tools/word-list-library/word-list-library.html');
INSERT INTO articles (slug, category, title, description, read_time, intro, sections, related_tool_label, related_tool_href) VALUES (N'meet-the-teacher-chinese-classroom-display', N'Printable Activities', N'Meet the Teacher in a Chinese Classroom: Make the Display Speak', N'Turn a Meet the Teacher display into comprehensible input with careful content, language layers, a student scavenger hunt, and clear privacy boundaries.', N'7 min read', N'["A Meet the Teacher display can become the first Chinese text students successfully understand. Keep it limited, repeated, and guessable: photos or icons supply context while short Chinese sentences provide comprehensible input.","Avoid covering the wall with a full biography. Choose details that naturally introduce classroom language: name, books, pets, places, food, routines, and a hope for the class."]', N'[{"heading":"Six small display zones","list":["我叫……: a large name and teacher title.","我来自……: a map and one place name.","我喜欢……: three images with three Chinese terms.","我的一天: three simple routine pictures.","我们的课堂: three positive, actionable agreements.","你呢？: one question students can answer on a sticky note."]},{"heading":"Layer Chinese, pinyin, and English","paragraphs":["Make Chinese the most prominent layer. Place smaller pinyin below it and use English only where meaning would otherwise remain unclear. Equal three-language translations encourage eyes to jump directly to English; for complete beginners, a picture and teacher gesture often support meaning more effectively."]},{"heading":"Day one: a five-minute display hunt","paragraphs":["Give partners three tasks: find one food the teacher likes, find one place, and find one classroom agreement. Students point first and attempt the Chinese second. During review, place each target term inside a short sentence and have the class repeat once."]},{"heading":"Turn the display into a speaking scaffold","paragraphs":["On day two, cover the teacher’s answers and let students use the same frames: 我叫……, 我喜欢……, and 我来自……. A student who prefers not to share personal information can introduce a fictional character or a person from a book."]},{"heading":"Privacy and professional boundaries","paragraphs":["Do not display a home address, personal phone number, precise daily schedule, or student information. Get permission from other people shown in photos; use illustrations or object photos when permission is uncertain."],"callout":"Share “I like tea” rather than “I am at this café every day at 4:00.” The display can model healthy digital and real-world privacy."},{"heading":"Keep it active after the first week","paragraphs":["Change the 你呢？ question monthly. When a new unit or celebration begins, pull one sentence from the display as a warm-up. A display becomes a resource only when students continue to point, read, ask, and respond."]}]', N'View more printable teaching resources', N'/resources?category=Printable%20Activities');
